$panelPath = Join-Path $PSScriptRoot '..\server\src\admin-panel\index.js'
$indexPath = Join-Path $PSScriptRoot '..\server\src\index.js'
$source = Get-Content -LiteralPath $panelPath -Raw

$source = $source.Replace("const defaults={appName:", "const ADMIN_ROLES=['super_admin','admin','moderator'];const ADMIN_PERMISSIONS=['dashboard.view','users.view','users.manage','quran.manage','hadith.manage','duas.manage','books.manage','lifestyle.manage','prophets.manage','settings.manage','content.publish','content.delete','admins.manage'];const ROLE_DEFAULTS={super_admin:['*'],admin:['dashboard.view','users.view','quran.manage','hadith.manage','duas.manage','books.manage','lifestyle.manage','prophets.manage','content.publish'],moderator:['dashboard.view','quran.manage','hadith.manage','duas.manage','books.manage','lifestyle.manage','prophets.manage']};`r`nconst defaults={appName:")
$source = $source.Replace("const token=jwt.sign({role:'admin',email,adminId:account._id.toString()},auth.jwtSecret,{expiresIn:'8h'});res.json({data:{token,email,expiresIn:'8h'}})", "const adminRole=ADMIN_ROLES.includes(account.role)?account.role:(email==='mdrokon909000@gmail.com'?'super_admin':'admin'),permissions=Array.isArray(account.permissions)?account.permissions:ROLE_DEFAULTS[adminRole];const token=jwt.sign({role:'admin',adminRole,permissions,email,adminId:account._id.toString()},auth.jwtSecret,{expiresIn:'8h'});res.json({data:{token,email,adminRole,permissions,expiresIn:'8h'}})")
$marker = "r.get('/api/app-config'"
$routes = @'
const superAdmin=(req,res,next)=>req.admin?.adminRole==='super_admin'||req.admin?.permissions?.includes('*')?next():res.status(403).json({message:'Super Admin access is required.'});
r.get('/api/admin/team',admin,superAdmin,async(_req,res)=>{const rows=await getAdmins().find({},{projection:{passwordHash:0,resetCodeHash:0}}).sort({createdAt:1}).toArray();res.json({data:{roles:ADMIN_ROLES,permissions:ADMIN_PERMISSIONS,items:rows.map(x=>({...x,id:x._id.toString(),_id:undefined,role:x.role||'admin',permissions:x.permissions||ROLE_DEFAULTS[x.role||'admin']}))}})});
r.post('/api/admin/team',admin,superAdmin,async(req,res)=>{try{const email=String(req.body.email||'').trim().toLowerCase(),password=String(req.body.password||''),role=ADMIN_ROLES.includes(req.body.role)?req.body.role:'moderator';if(!/^\S+@\S+\.\S+$/.test(email)||password.length<8)return res.status(400).json({message:'Valid email and an 8-character password are required.'});if(await getAdmins().findOne({email}))return res.status(409).json({message:'This admin email already exists.'});const permissions=role==='super_admin'?['*']:(Array.isArray(req.body.permissions)?req.body.permissions.filter(x=>ADMIN_PERMISSIONS.includes(x)):ROLE_DEFAULTS[role]);await getAdmins().insertOne({email,passwordHash:await bcrypt.hash(password,12),role,permissions,active:true,createdAt:new Date(),createdBy:req.admin.email});res.status(201).json({message:'Team member created.'})}catch(e){res.status(500).json({message:'Unable to create team member.'})}});
r.patch('/api/admin/team/:id',admin,superAdmin,async(req,res)=>{if(!ObjectId.isValid(req.params.id))return res.status(400).json({message:'Invalid admin ID.'});const role=ADMIN_ROLES.includes(req.body.role)?req.body.role:'moderator',permissions=role==='super_admin'?['*']:(Array.isArray(req.body.permissions)?req.body.permissions.filter(x=>ADMIN_PERMISSIONS.includes(x)):ROLE_DEFAULTS[role]),active=req.body.active!==false,target=await getAdmins().findOne({_id:new ObjectId(req.params.id)});if(!target)return res.status(404).json({message:'Team member not found.'});if(target.email==='mdrokon909000@gmail.com'&&(role!=='super_admin'||!active))return res.status(400).json({message:'The primary Super Admin cannot be disabled or demoted.'});await getAdmins().updateOne({_id:target._id},{$set:{role,permissions,active,updatedAt:new Date(),updatedBy:req.admin.email}});res.json({message:'Role and permissions updated.'})});
'@
$source = $source.Replace($marker, $routes + "`r`n" + $marker)
Set-Content -LiteralPath $panelPath -Value $source -Encoding utf8

$index = Get-Content -LiteralPath $indexPath -Raw
$old = "passwordHash:process.env.ADMIN_PASSWORD_HASH,active:true,createdAt:new Date()"
$new = "passwordHash:process.env.ADMIN_PASSWORD_HASH,role:process.env.ADMIN_EMAIL.trim().toLowerCase()==='mdrokon909000@gmail.com'?'super_admin':'admin',permissions:process.env.ADMIN_EMAIL.trim().toLowerCase()==='mdrokon909000@gmail.com'?['*']:['dashboard.view','users.view','quran.manage','hadith.manage','duas.manage','books.manage','lifestyle.manage','prophets.manage','content.publish'],active:true,createdAt:new Date()"
$index = $index.Replace($old,$new)
$index = $index.Replace("await adminUsers.createIndex({email:1},{unique:true});", "await adminUsers.createIndex({email:1},{unique:true});await adminUsers.updateOne({email:'mdrokon909000@gmail.com'},{`$set:{role:'super_admin',permissions:['*'],active:true,updatedAt:new Date()}});")
Set-Content -LiteralPath $indexPath -Value $index -Encoding utf8

